<?php
require_once dirname(__DIR__,2).'/app/bootstrap.php';require_admin();
$severity=(string)($_GET['severity']??'all');$allowed=['info','warning','critical'];$where='';$params=[];if(in_array($severity,$allowed,true)){$where='WHERE severity=:s';$params[':s']=$severity;}
$stmt=db()->prepare('SELECT id,actor_user_id,actor_role,event_key,severity,context_json,visitor_fingerprint,created_at FROM security_audit_logs '.$where.' ORDER BY id DESC LIMIT 250');$stmt->execute($params);$rows=$stmt->fetchAll();
$adminTitle='Security audit';include __DIR__.'/_header.php';
?>
<div class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">APPEND-ONLY EVENT HISTORY</span><h2>Security and authentication trail</h2><p>Passwords, invite tokens, raw IP addresses and secret values are excluded from the event payload.</p></div></div>
<form method="get" class="admin-filter"><label>Severity <select name="severity"><option value="all">All events</option><?php foreach($allowed as $v): ?><option value="<?= h($v) ?>" <?= $severity===$v?'selected':'' ?>><?= h(ucfirst($v)) ?></option><?php endforeach; ?></select></label><button class="button button-dark button-small">Filter</button></form>
<div class="table-wrap"><table class="admin-table"><thead><tr><th>Time</th><th>Event</th><th>Severity</th><th>Actor</th><th>Context</th></tr></thead><tbody><?php foreach($rows as $r): $ctx=json_decode((string)$r['context_json'],true); ?><tr><td><?= h($r['created_at']) ?></td><td><strong><?= h($r['event_key']) ?></strong></td><td><span class="status-pill <?= $r['severity']==='critical'?'status-rejected':($r['severity']==='warning'?'status-pending':'status-approved') ?>"><?= h($r['severity']) ?></span></td><td><?= h($r['actor_role']) ?><?= $r['actor_user_id']?' #'.(int)$r['actor_user_id']:'' ?></td><td><code><?= h(json_encode(is_array($ctx)?$ctx:[],JSON_UNESCAPED_UNICODE)) ?></code></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5" class="empty-admin">No matching audit records.</td></tr><?php endif; ?></tbody></table></div><p class="form-footnote">Audit retention is currently local and unbounded. Configure a production retention policy and external log sink before public deployment.</p></div>
<?php include __DIR__.'/_footer.php'; ?>
